import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const scriptDirectory = dirname(fileURLToPath(import.meta.url));
const projectDirectory = resolve(scriptDirectory, '..');
const source = resolve(projectDirectory, 'node_modules', 'apexcharts', 'dist', 'apexcharts.min.js');
const target = resolve(projectDirectory, 'src', 'vendor', 'apexcharts.ts');

await mkdir(dirname(target), { recursive: true });
const scriptSource = await readFile(source, 'utf8');
const generatedModule = [
  '// Generated by scripts/sync-apexcharts-asset.mjs. Do not edit manually.',
  'export const APEXCHARTS_SCRIPT = ' + JSON.stringify(scriptSource) + ';',
  '',
].join(String.fromCharCode(10));

await writeFile(target, generatedModule, 'utf8');
console.log('ApexCharts local script synced: ' + target);
